def solve(n, edges):
    visited = [False] * n
    graph = [[] for _ in range(n)]

    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    def dfs(node):
        if visited[node]:
            return
        visited[node] = True
        for neighbor in graph[node]:
            dfs(neighbor)

    components = 0
    for i in range(n):
        if not visited[i]:
            dfs(i)
            components += 1

    return components
