def solve(n, edges):
    # Initialize parent array for Union-Find
    parent = list(range(n))

    # Find function with path compression
    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    # Union function
    def union(x, y):
        root_x = find(x)
        root_y = find(y)
        if root_x != root_y:
            parent[root_y] = root_x

    # Perform union for each edge
    for u, v in edges:
        union(u, v)

    # Count unique roots (connected components)
    return len({find(i) for i in range(n)})
