def solve(n, roads):
    import heapq

    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in roads:
        graph[u].append((v, w))
        graph[v].append((u, w))

    # Function to perform Kruskal's algorithm
    def kruskal():
        # Sort all roads by weight
        sorted_roads = sorted(roads, key=lambda x: x[2])
        parent = list(range(n))
        rank = [1] * n

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            root_x = find(x)
            root_y = find(y)
            if root_x == root_y:
                return False
            if rank[root_x] < rank[root_y]:
                parent[root_x] = root_y
            else:
                parent[root_y] = root_x
                if rank[root_x] == rank[root_y]:
                    rank[root_x] += 1
            return True

        total_cost = 0
        for u, v, w in sorted_roads:
            if union(u, v):
                total_cost += w
        # Check if all cities are connected
        root = find(0)
        for i in range(1, n):
            if find(i) != root:
                return -1
        return total_cost

    # Function to perform Prim's algorithm
    def prim():
        visited = [False] * n
        min_heap = [(0, 0)]  # (cost, node)
        total_cost = 0
        while min_heap:
            cost, u = heapq.heappop(min_heap)
            if visited[u]:
                continue
            visited[u] = True
            total_cost += cost
            for v, w in graph[u]:
                if not visited[v]:
                    heapq.heappush(min_heap, (w, v))
        # Check if all cities are connected
        if sum(visited) != n:
            return -1
        return total_cost

    # Try both algorithms and return the result
    kruskal_result = kruskal()
    prim_result = prim()
    return kruskal_result if kruskal_result != -1 else prim_result
