import heapq

def solve(n, roads):
    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in roads:
        graph[u].append((v, w))
        graph[v].append((u, w))

    # Helper function to find minimum spanning tree using Kruskal's algorithm
    def kruskal():
        # Sort all roads by weight
        sorted_roads = sorted(roads, key=lambda x: x[2])
        parent = list(range(n))

        def find(u):
            while parent[u] != u:
                parent[u] = parent[parent[u]]
                u = parent[u]
            return u

        def union(u, v):
            root_u = find(u)
            root_v = find(v)
            if root_u == root_v:
                return False
            parent[root_v] = root_u
            return True

        total_cost = 0
        count = 0
        for u, v, w in sorted_roads:
            if union(u, v):
                total_cost += w
                count += 1
                if count == n - 1:
                    return total_cost
        return -1

    # Helper function to find minimum spanning tree using Prim's algorithm
    def prim():
        visited = [False] * n
        min_heap = [(0, 0)]  # (cost, node)
        total_cost = 0
        count = 0

        while min_heap:
            cost, u = heapq.heappop(min_heap)
            if visited[u]:
                continue
            visited[u] = True
            total_cost += cost
            count += 1
            if count == n:
                break
            for v, w in graph[u]:
                if not visited[v]:
                    heapq.heappush(min_heap, (w, v))
        if count == n:
            return total_cost
        return -1

    # Try both algorithms and return the result
    # Kruskal's algorithm is generally more efficient for sparse graphs
    result = kruskal()
    if result != -1:
        return result
    return prim()
