class BFS:
    def __init__(self, grid):
        self.grid = grid
        self.rows = len(grid)
        self.cols = len(grid[0]) if self.rows > 0 else 0

    def is_valid(self, r, c):
        return 0 <= r < self.rows and 0 <= c < self.cols and self.grid[r][c] == '.'

    def get_neighbors(self, r, c):
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        neighbors = []
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if self.is_valid(nr, nc):
                neighbors.append((nr, nc))
        return neighbors

def solve(grid, start, goal):
    if not grid or not grid[0]:
        return []
    rows, cols = len(grid), len(grid[0])
    if start[0] < 0 or start[0] >= rows or start[1] < 0 or start[1] >= cols or grid[start[0]][start[1]] == '#':
        return []
    if goal[0] < 0 or goal[0] >= rows or goal[1] < 0 or goal[1] >= cols or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    bfs = BFS(grid)
    visited = [[False for _ in range(cols)] for _ in range(rows)]
    queue = [(start[0], start[1], [start])]

    while queue:
        r, c, path = queue.pop(0)
        if (r, c) == goal:
            return path
        visited[r][c] = True
        for nr, nc in bfs.get_neighbors(r, c):
            if not visited[nr][nc]:
                new_path = path + [(nr, nc)]
                queue.append((nr, nc, new_path))

    return []
