using namespace std;

vector<pair<int, int>> solve(vector<string> grid, pair<int, int> start, pair<int, int> goal) {
    int rows = grid.size();
    int cols = grid[0].size();

    // Check if start or goal is a wall
    if (grid[start.first][start.second] == '#' || grid[goal.first][goal.second] == '#') {
        return {};
    }

    // If start is the same as goal
    if (start == goal) {
        return {start};
    }

    // Directions: up, down, left, right
    vector<pair<int, int>> directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    // BFS setup
    queue<pair<int, int>> q;
    q.push(start);

    // To keep track of visited cells
    vector<vector<bool>> visited(rows, vector<bool>(cols, false));
    visited[start.first][start.second] = true;

    // To reconstruct the path
    vector<vector<pair<int, int>>> prev(rows, vector<pair<int, int>>(cols, {-1, -1}));

    while (!q.empty()) {
        int row = q.front().first;
        int col = q.front().second;
        q.pop();

        for (auto dir : directions) {
            int newRow = row + dir.first;
            int newCol = col + dir.second;

            // Check if the new position is valid
            if (newRow >= 0 && newRow < rows && newCol >= 0 && newCol < cols &&
                grid[newRow][newCol] == '.' && !visited[newRow][newCol]) {
                visited[newRow][newCol] = true;
                prev[newRow][newCol] = {row, col};
                q.push({newRow, newCol});

                // If goal is reached, reconstruct the path
                if (newRow == goal.first && newCol == goal.second) {
                    vector<pair<int, int>> path;
                    int currRow = newRow, currCol = newCol;
                    while (currRow != -1 && currCol != -1) {
                        path.push_back({currRow, currCol});
                        tie(currRow, currCol) = prev[currRow][currCol];
                    }
                    reverse(path.begin(), path.end());
                    return path;
                }
            }
        }
    }

    // No path found
    return {};
}
