#include <iostream>
#include <vector>
#include <queue>
using namespace std;

vector<vector<int>> bfs(vector<vector<int>>& grid, int startRow, int startCol, int goalRow, int goalCol) {
    int rows = grid.size();
    int cols = grid[0].size();
    vector<vector<bool>> visited(rows, vector<bool>(cols, false));
    queue<pair<int, int>> q;
    q.push({startRow, startCol});
    visited[startRow][startCol] = true;
    vector<vector<int>> parent(rows, vector<int>(cols, -1));

    while (!q.empty()) {
        int r = q.front().first;
        int c = q.front().second;
        q.pop();

        if (r == goalRow && c == goalCol) {
            break;
        }

        int dirs[4][2] = {{-1,0}, {1,0}, {0,-1}, {0,1}};
        for (int i = 0; i < 4; ++i) {
            int nr = r + dirs[i][0];
            int nc = c + dirs[i][1];
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && !visited[nr][nc] && grid[nr][nc] == 1) {
                visited[nr][nc] = true;
                parent[nr][nc] = (r * cols + c) * 4 + i; // Store direction to track path
                q.push({nr, nc});
            }
        }
    }

    // Reconstruct path
    vector<int> path;
    int current = goalRow * cols + goalCol;
    while (current != -1) {
        path.push_back(current);
        current = parent[current / cols][current % cols];
    }

    reverse(path.begin(), path.end());

    // Convert to row, col pairs
    vector<vector<int>> result;
    for (int p : path) {
        result.push_back({p / cols, p % cols});
    }

    return result;
}

vector<vector<int>> solve(vector<vector<int>>& grid, pair<int, int> start, pair<int, int> goal) {
    int rows = grid.size();
    int cols = grid[0].size();

    if (start.first < 0 || start.first >= rows || start.second < 0 || start.second >= cols ||
        goal.first < 0 || goal.first >= rows || goal.second < 0 || goal.second >= cols ||
        grid[start.first][start.second] == 0 || grid[goal.first][goal.second] == 0) {
        return {};
    }

    if (start.first == goal.first && start.second == goal.second) {
        return {{start.first, start.second}};
    }

    return bfs(grid, start.first, start.second, goal.first, goal.second);
}
