        if col > 0 and grid[row][col - 1] != '#':
            neighbors.append((row, col - 1))
        if col < cols - 1 and grid[row][col + 1] != '#':
            neighbors.append((row, col + 1))
        return neighbors

    def dfs(row, col):
        if (row, col) == goal:
            path.append((row, col))
            return True
        visited.add((row, col))
        path.append((row, col))
        for neighbor_row, neighbor_col in get_neighbors(row, col):
            if (neighbor_row, neighbor_col) not in visited:
                if dfs(neighbor_row, neighbor_col):
                    return True
        path.pop()
        return False

    if dfs(x, y):
        return path
    else:
        return []
