        camino.pop()
        fila[fila][col] = False
        return False

    if not es_valido(start[0], start[1]) or not es_valido(goal[0], goal[1]):
        return []

    if start == goal:
        return [start]

    if dfs(start[0], start[1]):
        return camino
    else:
        return []
