def solve(n, roads):
    import heapq

    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in roads:
        graph[u].append((v, w))
        graph[v].append((u, w))

    # Utility to find minimum spanning tree using Kruskal's algorithm
    def kruskal():
        # Sort all roads by weight
        sorted_roads = sorted(roads, key=lambda x: x[2])

        # Initialize parent array for union-find
        parent = list(range(n))

        def find(u):
            while parent[u] != u:
                parent[u] = parent[parent[u]]
                u = parent[u]
            return u

        def union(u, v):
            root_u = find(u)
            root_v = find(v)
            if root_u == root_v:
                return False
            parent[root_v] = root_u
            return True

        total_cost = 0
        edges_used = 0

        for u, v, w in sorted_roads:
            if union(u, v):
                total_cost += w
                edges_used += 1
                if edges_used == n - 1:
                    break

        # Check if all cities are connected
        root = find(0)
        for i in range(1, n):
            if find(i) != root:
                return -1

        return total_cost

    # Utility to find minimum spanning tree using Prim's algorithm
    def prim():
        # Adjacency list
        adj = [[] for _ in range(n)]
        for u, v, w in roads:
            adj[u].append((v, w))
            adj[v].append((u, w))

        # Priority queue (min-heap)
        heap = [(0, 0)]  # (cost, node)
        visited = [False] * n
        total_cost = 0
        edges_used = 0

        while heap:
            cost, u = heapq.heappop(heap)
            if visited[u]:
                continue
            visited[u] = True
            total_cost += cost
            edges_used += 1
            if edges_used == n:
                break

            for v, w in adj[u]:
                if not visited[v]:
                    heapq.heappush(heap, (w, v))

        # Check if all cities are connected
        if sum(visited) != n:
            return -1

        return total_cost

    # Try both algorithms and return the minimum cost
    # If both fail, return -1
    cost_kruskal = kruskal()
    cost_prim = prim()

    if cost_kruskal == -1 and cost_prim == -1:
        return -1
    elif cost_kruskal == -1:
        return cost_prim
    elif cost_prim == -1:
        return cost_kruskal
    else:
        return min(cost_kruskal, cost_prim)
