    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in roads:
        graph[u].append((v, w))
        graph[v].append((u, w))

    # Utility to find minimum spanning tree using Prim's algorithm
    def prim():
        visited = [False] * n
        min_heap = [(0, 0)]  # (cost, node)
        total_cost = 0

        while min_heap:
            cost, u = heapq.heappop(min_heap)
            if visited[u]:
                continue
            visited[u] = True
            total_cost += cost
            for v, w in graph[u]:
                if not visited[v]:
                    heapq.heappush(min_heap, (w, v))

        # Check if all nodes are visited
        if sum(visited) != n:
            return -1
        return total_cost

    return prim()
