def solve(n, roads):
    import heapq

    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in roads:
        graph[u].append((v, w))
        graph[v].append((u, w))

    # Floyd-Warshall to find all pairs shortest paths
    dist = [[float('inf')] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0

    for u, v, w in roads:
        dist[u][v] = min(dist[u][v], w)
        dist[v][u] = min(dist[v][u], w)

    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][k] + dist[k][j] < dist[i][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    # Kruskal's algorithm to find MST using the shortest paths
    edges = []
    for i in range(n):
        for j in range(i + 1, n):
            if dist[i][j] < float('inf'):
                edges.append((dist[i][j], i, j))

    edges.sort()

    parent = list(range(n))

    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u

    def union(u, v):
        root_u = find(u)
        root_v = find(v)
        if root_u == root_v:
            return False
        parent[root_v] = root_u
        return True

    total_cost = 0
    count = 0
    for w, u, v in edges:
        if union(u, v):
            total_cost += w
            count += 1
            if count == n - 1:
                break

    if count != n - 1:
        return -1
    return total_cost
