def solve(height):
    if not height:
        return 0
    from collections import deque
    n = len(height)
    left = [0] * n
    right = [0] * n
    q = deque()
    q.append(0)
    while q:
        i = q.popleft()
        if i >= n:
            break
        if left[i] == 0:
            left[i] = height[i]
        else:
            left[i] = max(left[i], height[i])
        if i + 1 < n and height[i + 1] < height[i]:
            q.append(i + 1)
    q.append(n - 1)
    while q:
        i = q.popleft()
        if i < 0:
            break
        if right[i] == 0:
            right[i] = height[i]
        else:
            right[i] = max(right[i], height[i])
        if i - 1 >= 0 and height[i - 1] < height[i]:
            q.append(i - 1)
    total = 0
    for i in range(n):
        total += min(left[i], right[i]) - height[i]
    return total
