    while i < len(left_indices) and j < len(right_indices):
        if left_indices[i] == right_indices[j]:
            valid_indices.append(left_indices[i])
            i += 1
            j += 1
        elif left_indices[i] < right_indices[j]:
            i += 1
        else:
            j += 1

    # Calculate trapped water
    total_water = 0
    for i in range(1, len(valid_indices)):
        left = valid_indices[i-1]
        right = valid_indices[i]
        min_height = min(height[left], height[right])
        total_water += min_height * (right - left - 1)

    return total_water
