    if not height:
        return 0

    left_indices = []
    right_indices = []

    # Fill left indices with increasing order
    for i in range(len(height)):
        if not left_indices or height[i] > height[left_indices[-1]]:
            left_indices.append(i)

    # Fill right indices with decreasing order
    for i in range(len(height)-1, -1, -1):
        if not right_indices or height[i] > height[right_indices[-1]]:
            right_indices.append(i)

    # Use two pointers to calculate trapped water
    left = 0
    right = 0
    total = 0
    while left < len(left_indices) and right < len(right_indices):
        if left_indices[left] < right_indices[right]:
            total += height[right_indices[right]] - height[left_indices[left]]
            left += 1
        else:
            total += height[left_indices[left]] - height[right_indices[right]]
            right += 1

    return total
```

